"use strict";
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),cp=require('node:child_process');
const C=require('./match-contract-evidence-closure-v0.1-capture.cjs'),source=C.json(C.prefix+'source-evidence.json'),findings=C.json(C.prefix+'findings-evidence.json'),plan=C.json(C.prefix+'plan-evidence.json');
const integrity=C.integrity();assert.equal(integrity.preservedExistingHashes,1494);
for(const s of source.exactSnippets){assert.equal(C.fileHash(s.path),s.sha256);const current=fs.readFileSync(path.join(C.root,s.path),'utf8').split(/\r?\n/).slice(s.startLine-1,s.endLine).join('\n')+'\n';assert.equal(current,s.source);}
for(const s of source.diagnosticSources)assert.equal(C.fileHash(s.path),s.sha256);
for(const [p,h] of Object.entries(source.dependencyHashes))assert.equal(C.fileHash(p),h,p);
for(const row of findings.rawExecutions){assert.equal(C.fileHash(row.path),row.sha256);assert.equal(C.fileHash(row.witnessPath),row.witnessSha256);const raw=C.json(row.path);assert.equal(raw.status,'PASS');assert(raw.entryVerified&&raw.sourceStable);assert.equal(raw.exitCode,0);assert(new Date(raw.startedAt)>new Date(plan.createdAt));for(const [p,h] of Object.entries(raw.relevantSourceHashesAfter))assert.equal(C.fileHash(p),h,p);}
assert(Object.values(findings.taskA.replay).every(Boolean));assert.equal(findings.taskA.summary.seed,88222);assert.equal(findings.taskA.summary.original37Boolean,true);assert.equal(findings.taskA.record.eventRefs.length,113);assert.equal(findings.taskA.recordIntegrity.accepted,true);assert.deepEqual(findings.taskA.record.result.finalScore,{away:3,home:1});assert.equal(findings.taskA.summary.safety,107);
assert(Object.values(findings.taskB.checks).every(Boolean));assert.equal(findings.taskB.originalAssertion,source.originalFormalTest.original38);assert.equal(findings.taskB.originalFormatterBodyMatchesCurrentSource,true);
assert.equal(findings.taskC.candidateCount,1);assert.equal(findings.taskC.status,'UNVERIFIED');assert.equal(findings.taskC.finalOffenseTicks,0);assert.equal(findings.taskC.gateTrueTicks.length,2);assert(findings.taskC.gateTrueTicks.every(t=>t.before.outs===3));assert.equal(findings.taskC.liveFinalGateTicks,0);
assert(findings.acceptanceMatrix.every(x=>x.formallyReplaced===false));assert.equal(findings.executionTotals.diagnosticChildren,3);assert.equal(findings.executionTotals.canonicalFullMatchExecutions,2);assert.equal(findings.executionTotals.seed88221FullMatches,0);
const canonical=fs.readFileSync(path.join(C.root,C.prefix+'canonical.cjs'),'utf8');assert(!/\bm\.(?:simulationPhase|rosters|lineup|completedMoments|outs|currentBatter)\s*=(?!=)|completedMoments\.(?:push|splice|unshift)\s*\(/.test(canonical),'Canonical/C must not mutate admission/phase/Moment/out state');
const test=fs.readFileSync(path.join(C.root,plan.tasks.B.test),'utf8'),prefix=test.slice(0,test.indexOf('verify("1.')),routine=fs.readFileSync(path.join(C.root,C.prefix+'routine.cjs'),'utf8');assert.equal(prefix,plan.tasks.B.originalPrefix);assert(routine.startsWith(prefix));assert.equal(routine.split(plan.tasks.B.assertion38).length-1,1);
const report=fs.readFileSync(path.join(C.root,C.report),'utf8'),links=[...report.matchAll(/\]\(([^)]+)\)/g)].map(m=>m[1]),pending=[C.prefix+'verification-evidence.json',C.prefix+'closeout-evidence.json',C.prefix+'delivery-evidence.json'];
for(const href of links){const p=path.resolve(C.root,'docs',href.split('#')[0]);assert(fs.existsSync(p)||pending.some(f=>path.resolve(C.root,f)===p),'Missing report link '+href);}
for(const text of ['Ready for Phase B2','Ready for Commit','Ready for Sprint10B','UNVERIFIED','214','1494','222201'])assert(report.includes(text),text);
const scripts=C.files().filter(p=>C.isNew(p)&&p.endsWith('.cjs'));
const syntax=scripts.map(file=>{const args=['--check',path.join(C.root,file)],r=cp.spawnSync(process.execPath,args,{cwd:C.root,encoding:'utf8',windowsHide:true,timeout:10000,maxBuffer:1000000});assert.equal(r.status,0,r.stderr);return{file,actualCommand:[process.execPath,...args],entry:'Node syntax-only',stdout:r.stdout,stderr:r.stderr,exitCode:r.status,signal:r.signal,error:r.error?.message||null,timeoutMs:10000};});
const directSources=[C.prefix+'verify.cjs',C.prefix+'finalize.cjs'].map(p=>({path:p,sha256:C.fileHash(p),source:fs.readFileSync(path.join(C.root,p),'utf8')}));
C.capture('verification',{...integrity,report:{path:C.report,sha256:C.fileHash(C.report),linksChecked:links.length,onlyPendingLinks:pending},source:{path:C.prefix+'source-evidence.json',sha256:C.fileHash(C.prefix+'source-evidence.json'),exactSnippetCount:10,allCurrent:true},syntax,directSources,acceptedChildren:findings.rawExecutions,additionalReadOnlyChecks:{planPrecedesAllChildren:true,replayAllFiveHashesAndDecisionsEqual:true,original38PrefixAndAssertionPreserved:true,originalFormatterBodyMatchesCurrentSource:true,canonicalAndCMemoryEditsForbiddenFieldsAbsent:true,S3SingleCandidateAndNoLiveFinalGate:true,allOriginalRowsNotFormallyReplaced:true},acceptance:{TaskA:'CONFIRMED bounded Canonical #37 responsibility',TaskB:'CONFIRMED isolated exact original #38 predicate',TaskC:'UNVERIFIED',prior36:'FAIL retained, not rerun',priorC9:'CONTRACT GAP carried forward, not re-audited'},executions:findings.executionTotals,productionDelta:0,formalTestDelta:0,existingFixtureSeedPinDelta:0,phaseB2Started:false,readyForPhaseB2:'NO',readyForCommit:'NO',readyForSprint10B:'NO',receiverV2:'DISABLED'});
console.log(JSON.stringify({verification:'PASS',existingHashes:1494,sourceSnippets:10,syntaxFiles:syntax.length,reportLinks:links.length,diagnosticChildren:3,fullMatches:2,seed88221FullMatches:0,TaskA:'CONFIRMED',TaskB:'CONFIRMED isolated',TaskC:'UNVERIFIED',readyForPhaseB2:'NO'}));

"use strict";
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const C=require('./match-contract-evidence-closure-v0.1-capture.cjs'),v=C.json(C.prefix+'verification-evidence.json'),integrity=C.integrity();
assert.equal(C.fileHash(C.report),v.report.sha256);
C.capture('closeout',{...integrity,report:v.report,verification:{path:C.prefix+'verification-evidence.json',sha256:C.fileHash(C.prefix+'verification-evidence.json')},findings:{path:C.prefix+'findings-evidence.json',sha256:C.fileHash(C.prefix+'findings-evidence.json')},TaskA:'CONFIRMED canonical88222 / replay',TaskB:'CONFIRMED exact isolated #38 synthetic predicate',TaskC:'UNVERIFIED single predeclared candidate; no extension',old36:'FAIL retained; no new original suite invocation',oldC9:'CONTRACT GAP retained; no re-audit or fix',executions:v.executions,phaseB2Started:false,receiverV2:'DISABLED',L03:'PARTIAL',readyForPhaseB2:'NO',readyForCommit:'NO',readyForSprint10B:'NO',resetCleanStashStageCommitPush:false,stopped:true});
const files=C.files().filter(C.isNew),hashes=Object.fromEntries(files.map(p=>[p,C.fileHash(p)]));
C.capture('delivery',{files,hashes,deliverySelfHashExcluded:true,unchangedExistingHashes:1494,changedExistingPaths:[],productionDelta:0,formalTestDelta:0,existingFixtureSeedPinDelta:0,oldCapturesPreserved:true,protectedMetadataUnchanged:true,readyForPhaseB2:'NO',readyForCommit:'NO',readyForSprint10B:'NO',receiverV2:'DISABLED',stopped:true});
const links=[...fs.readFileSync(path.join(C.root,C.report),'utf8').matchAll(/\]\(([^)]+)\)/g)].map(m=>m[1]);for(const href of links)assert(fs.existsSync(path.resolve(C.root,'docs',href.split('#')[0])),href);
for(const [p,h] of Object.entries(hashes))assert.equal(C.fileHash(p),h,p);C.integrity();
console.log(JSON.stringify({report:C.report,existingHashesPreserved:1494,newArtifacts:files.length+1,linksResolved:links.length,indexEmpty:integrity.git.index==='',productionDelta:0,formalTestDelta:0,TaskA:'CONFIRMED',TaskB:'CONFIRMED isolated',TaskC:'UNVERIFIED',readyForPhaseB2:'NO',stopped:true}));
